import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  random,
} from '../remotionShim';
// Font Loading
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: oswaldFamily } = loadOswald();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();

// Schema Definition


export type HousingCrisisAlertProps = Record<string, any>;

// House Icon Component handling the glitch and explosion logic
const GlitchingHouse: React.FC<{
  explodeProgress: number;
  glitchX: number;
  glitchY: number;
  color: string;
  doorColor: string;
  opacity: number;
  scale: number;
}> = ({ explodeProgress, glitchX, glitchY, color, doorColor, opacity, scale }) => {
  // Explosion trajectories
  const roofX = interpolate(explodeProgress, [0, 1], [0, -150]) + glitchX;
  const roofY = interpolate(explodeProgress, [0, 1], [0, -400]) + glitchY;
  const roofR = interpolate(explodeProgress, [0, 1], [0, -65]);

  const baseX = interpolate(explodeProgress, [0, 1], [0, -250]) + glitchX;
  const baseY = interpolate(explodeProgress, [0, 1], [0, 150]) + glitchY;
  const baseR = interpolate(explodeProgress, [0, 1], [0, 45]);

  const doorX = interpolate(explodeProgress, [0, 1], [0, 300]) + glitchX;
  const doorY = interpolate(explodeProgress, [0, 1], [0, -200]) + glitchY;
  const doorR = interpolate(explodeProgress, [0, 1], [0, 130]);

  return (
    <div style={{ transform: `scale(${scale})`, transition: "none" }}>
      <svg
        width="140"
        height="140"
        viewBox="0 0 140 140"
        style={{
          opacity,
          transition: "none",
          overflow: "visible",
        }}
      >
        {/* Roof */}
        <g
          style={{
            transform: `translate(${roofX}px, ${roofY}px) rotate(${roofR}deg)`,
            transformOrigin: "70px 40px",
            transition: "none",
          }}
        >
          <polygon points="10,70 70,10 130,70" fill={color} />
        </g>
        {/* Base */}
        <g
          style={{
            transform: `translate(${baseX}px, ${baseY}px) rotate(${baseR}deg)`,
            transformOrigin: "70px 105px",
            transition: "none",
          }}
        >
          <rect x="25" y="70" width="90" height="70" fill={color} />
        </g>
        {/* Door */}
        <g
          style={{
            transform: `translate(${doorX}px, ${doorY}px) rotate(${doorR}deg)`,
            transformOrigin: "70px 115px",
            transition: "none",
          }}
        >
          <rect x="55" y="90" width="30" height="50" fill={doorColor} />
        </g>
      </svg>
    </div>
  );
};

// Main Component
const HousingCrisisAlert: React.FC<HousingCrisisAlertProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 10,
  bannerColor = "#D32F2F",
  textColor = "#FFFFFF",
  alertHeadline = "HOUSING CRISIS",
  glitchIntensity = 25,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background safely parsed
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings
  const bannerEnterStart = 5;
  const textEnterStart = 20;
  const glitchStart = 55;
  const explodeStart = 85;

  // 1. Banner Slide Animation
  const bannerSlide = spring({
    frame: Math.max(0, frame - bannerEnterStart),
    fps,
    config: { damping: 14, stiffness: 120 },
  });
  // Banner slides up from below the visible area
  const bannerTranslateY = interpolate(bannerSlide, [0, 1], [400, 0]);

  // 2. Text Appearance
  const textScaleSpring = spring({
    frame: Math.max(0, frame - textEnterStart),
    fps,
    config: { damping: 12, stiffness: 150 },
  });
  const textScale = interpolate(textScaleSpring, [0, 1], [0.85, 1]);
  const textOpacity = interpolate(textScaleSpring, [0, 0.5], [0, 1], {
    extrapolateRight: "clamp",
  });

  // 3. Glitch Logic
  const isGlitching = frame >= glitchStart && frame < explodeStart;
  const glitchAmount = isGlitching ? glitchIntensity : 0;

  // Deterministic random offsets based on frame
  const gX = isGlitching
    ? interpolate(random(`x-${frame}`), [0, 1], [-glitchAmount, glitchAmount])
    : 0;
  const gY = isGlitching
    ? interpolate(random(`y-${frame}`), [0, 1], [-glitchAmount * 0.5, glitchAmount * 0.5])
    : 0;

  // 4. Explode / Break Apart Logic
  const explodeProgress = spring({
    frame: Math.max(0, frame - explodeStart),
    fps,
    config: { damping: 14, stiffness: 90 },
  });

  const explodeOpacity = interpolate(explodeProgress, [0.4, 1], [1, 0], {
    extrapolateRight: "clamp",
  });

  // 5. Ticker Animation
  const tickerSpeed = 6;
  const tickerTranslateX = -(frame * tickerSpeed);
  const tickerText =
    "/// SEVERE HOUSING SHORTAGE /// MARKET INSTABILITY /// MILLIONS AFFECTED /// EVICTION RATES SOARING /// FORECLOSURES RISING /// LOCAL SHELTERS OVERCAPACITY /// LEGISLATION PENDING ".repeat(
      10
    );

  // Responsive scaling factor
  const baseScale = width / 1920;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Container for the lower third news graphic */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.08,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          transform: `translateY(${bannerTranslateY}px)`,
          transition: "none",
          zIndex: 10,
        }}
      >
        {/* 'URGENT ALERT' Badge */}
        <div
          style={{
            backgroundColor: "#FFFFFF",
            color: bannerColor,
            padding: `${12 * baseScale}px ${32 * baseScale}px`,
            fontSize: 28 * baseScale,
            fontFamily: oswaldFamily,
            fontWeight: 700,
            letterSpacing: "0.1em",
            display: "inline-block",
            alignSelf: "flex-start",
            marginLeft: "5%",
            boxShadow: "0px 10px 20px rgba(0,0,0,0.3)",
            zIndex: 2,
            transition: "none",
          }}
        >
          URGENT ALERT
        </div>

        {/* Main Red Banner */}
        <div
          style={{
            backgroundColor: bannerColor,
            width: "100%",
            height: 160 * baseScale,
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            paddingLeft: "5%",
            boxShadow: "0px 15px 40px rgba(0,0,0,0.5)",
            position: "relative",
            overflow: "hidden",
            transition: "none",
          }}
        >
          {/* Subtle Scanline Overlay for Broadcast Feel */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                "repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0,0,0,0.15) 2px, rgba(0,0,0,0.15) 4px)",
              pointerEvents: "none",
              zIndex: 1,
              transition: "none",
            }}
          />

          {/* Icon Container */}
          <div
            style={{
              position: "relative",
              width: 140 * baseScale,
              height: 140 * baseScale,
              marginRight: 40 * baseScale,
              zIndex: 5,
              transition: "none",
            }}
          >
            {/* Glitch RGB Separation Layers */}
            {isGlitching && (
              <>
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    mixBlendMode: "screen",
                    opacity: 0.8,
                    transition: "none",
                  }}
                >
                  <GlitchingHouse
                    explodeProgress={0}
                    glitchX={gX * 1.5}
                    glitchY={-gY}
                    color="#00FFFF"
                    doorColor="#00FFFF"
                    opacity={1}
                    scale={baseScale}
                  />
                </div>
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    mixBlendMode: "screen",
                    opacity: 0.8,
                    transition: "none",
                  }}
                >
                  <GlitchingHouse
                    explodeProgress={0}
                    glitchX={-gX * 1.5}
                    glitchY={gY}
                    color="#FF00FF"
                    doorColor="#FF00FF"
                    opacity={1}
                    scale={baseScale}
                  />
                </div>
              </>
            )}

            {/* Main House Layer */}
            <div
              style={{
                position: "absolute",
                inset: 0,
                zIndex: 10,
                transition: "none",
              }}
            >
              <GlitchingHouse
                explodeProgress={explodeProgress}
                glitchX={gX}
                glitchY={gY}
                color={textColor}
                doorColor={bannerColor}
                opacity={explodeOpacity}
                scale={baseScale}
              />
            </div>
          </div>

          {/* Headline Text */}
          <div
            style={{
              fontFamily: oswaldFamily,
              fontSize: 96 * baseScale,
              color: textColor,
              fontWeight: 700,
              textTransform: "uppercase",
              letterSpacing: "0.05em",
              lineHeight: 1,
              transform: `scale(${textScale})`,
              opacity: textOpacity,
              transformOrigin: "left center",
              zIndex: 5,
              transition: "none",
              textShadow: "2px 4px 10px rgba(0,0,0,0.4)",
            }}
          >
            {alertHeadline}
          </div>
        </div>

        {/* Ticker Bar */}
        <div
          style={{
            backgroundColor: "#000000",
            width: "100%",
            height: 48 * baseScale,
            display: "flex",
            alignItems: "center",
            overflow: "hidden",
            position: "relative",
            zIndex: 1,
            transition: "none",
          }}
        >
          <div
            style={{
              color: "#FFD600",
              fontFamily: robotoMonoFamily,
              fontSize: 22 * baseScale,
              fontWeight: 600,
              whiteSpace: "nowrap",
              transform: `translateX(${tickerTranslateX}px)`,
              transition: "none",
            }}
          >
            {tickerText}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default HousingCrisisAlert;